-- GENERATED by `wfj generate` from data/gossip/gossip-a5.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a500b88994a580cd"] = { "Sei qui per conoscere le battaglie vinte e perse su questo campo? Qui non ci sono vincitori...", "." },
  ["a50e5b91faa0e470"] = { "Arriva {name}: occhi aperti, amici!", "." },
  ["a50f413135b40a7d"] = { "Ciao! Ho una proposta per <un/una> <avventuriero/avventuriera> come te, se te la senti di accettare la sfida!\n\nOltre a lavorare alla mia invenzione, il Super Egg-O-Matic, sto dando una mano ai druidi nella loro campagna per salvare gli ippogrifi. Gli uccelli subiscono gli effetti malvagi degli ogre Gordunni che abitano le rovine di Feralas, e il loro numero si sta riducendo.\n\nIo raccolgo uova di molti tipi diversi. Mi aiuti a trovarne qualcuna?", "." },
  ["a51a267d40282baf"] = { "Per metterti alla prova contro le ⟦Burning Blade=Lame Ardenti⟧, devi prima sconfiggere i loro Vile Familiar. Torna da me quando l'avrai fatto.", "." },
  ["a51b747570c96e5a"] = { "Non puoi salvarlo!", "." },
  ["a539d806dab7e23b"] = { "Soldati Theoric, Kitrin, Blythe, Agmond...", "." },
  ["a53afb061ef2f5f2"] = { "Che lo spargimento di sangue abbia inizio!", "." },
  ["a54063f3a5aed0de"] = { "L'⟦Horde=Orda⟧ sta accumulando una gran quantità di bende. Finora sono state raccolte $2079w Bende di Lana su $2080w. Sono state create $2085w Bende di Telamagica su $2086w. E sono state raccolte $2089w Bende di Telarunica su $2090w.", "." },
  ["a54df7664cc87982"] = { "Ben fatto, miei servitori. Il coraggio dei mortali comincia a vacillare! Ora vediamo come se la cavano con il vero Signore dei ⟦Blackrock Spire=Bastioni di Roccianera⟧!!!", "." },
  ["a55284d87b7fc74d"] = { "{name} ha attaccato il fabbro!", "." },
  ["a5580f2b54c5c4b9"] = { "Sei un'ispirazione per tutti noi, signore.", "." },
  ["a55d72f99b174e0e"] = { "Eccellente, ti sei <dimostrato/dimostrata> <degno/degna>! E ora la fase successiva del tuo addestramento...", "." },
  ["a5639174d2be7231"] = { "Dov'è il maestro di guerra Garrick?", "." },
  ["a563c9d12fd4d559"] = { "Solo un assaggio...", "." },
  ["a565167fc1e36dac"] = { "Così arrabbiato, Sarok? Non dovresti bere così tanto... Dicci solo cosa sai di Mosarn.", "." },
  ["a56708df7b0ff02f"] = { "Vieni a parlare con me se hai intenzione di andare a Gnomeregan, {name}!", "." },
  ["a56abe33a1052e48"] = { "La tua stessa forza mi nutre, {name}!", "." },
  ["a56fb7fbffc35698"] = { "Ecco qui, Relara. Prendi questo...", "." },
  ["a574f288a8bd9ffb"] = { "Ciao! Sono appena di ritorno da un'esplorazione delle Rovine di Kel'Theril, a sud-ovest. Ora intendo studiare i silvagufi che vivono proprio in cima alla cresta, nella ⟦Owl Wing Thicket=Selva Ala di Gufo⟧.\n\nHai parlato con ⟦Erelas Ambersky=Erelas Cieloambrato⟧ a ⟦Rut'theran Village=Rut'theran⟧? È stato lui a chiedermi di venire qui, e forse ha un compito anche per te.", "." },
  ["a579164b914de452"] = { "Sta arrivando un vento feroce: me lo dice il dolore al ginocchio scoperto. Spero solo che non ci travolga.", "." },
  ["a57cdcf8d3d376db"] = { "Voglio vedere la tua merce.", "." },
  ["a5876f69a59e99b9"] = { "Salve, Rayne. Cosa porta il ⟦Cenarion Circle=Circolo Cenariano⟧ nelle ⟦Plaguelands=Terre Infette⟧?", "." },
  ["a58ac1e90b2701b1"] = { "Mi sorprende molto che qualcuno così sbadato sia arrivato fin qui...\n\nSì, puoi avere un altro amuleto, ma Mau'ari è molto scontenta di quello che hai fatto!\n\nOra va'.", "." },
  ["a58fbba844e29404"] = { "La terra di Feralas ha passato molto, {race}. La terra, gli alberi, le creature: tutti stanno cambiando ciò che Feralas è e sarà.\n\nMa i Colossi Gemelli sopra di noi restano immutati, nonostante tutto ciò che è accaduto qui...", "." },
  ["a593af16dfee2921"] = { "Combattete per le vostre famiglie! Non arrendetevi!", "." },
  ["a5a8bf8ed8117045"] = { "Mmm... Quella roccia è bella, ma troppo piccola.", "." },
  ["a5a9aded2f30d37b"] = { "Sii <guarito/guarita>, <sacerdote/sacerdotessa>.", "." },
  ["a5b4e45761cacafe"] = { "Fammi sapere se ti serve qualcos'altro!", "." },
  ["a5b8c28b928ca565"] = { "Questo monumento è dedicato a tutti coloro che sono caduti per proteggere ⟦Stormwind=Roccavento⟧. La nostra gente ha sopportato difficoltà incredibili per conservare la propria libertà e decidere del proprio destino. È qui che ricordiamo ogni sacrificio compiuto dai nostri cittadini durante la prima guerra che ha martoriato il nostro popolo.", "." },
  ["a5bbbc8e6a610213"] = { "Che bontà. Adoro lo zampalunga delle pianure arrosto.", "." },
  ["a5c504868cfbb018"] = { "Dimmi di più, Trenton.", "." },
  ["a5ddc5a77460efa7"] = { "Per allestire un accampamento tutto tuo ti basta un semplice fuoco da campo. Di solito i cuochi possono insegnarti a farne uno.", "." },
  ["a5e099c15c95fd73"] = { "Abbiamo difficoltà a determinare lo stato della piaga nella zona; ripassa tra poco e forse ne sapremo di più.", "." },
  ["a5e1058c3d47aac7"] = { "La somma sacerdotessa banchetterà con le tue ossa!", "." },
  ["a5e87fb4f7db822e"] = { "Chi osa turbare la sacralità di Eldre'Thalas? Affrontatemi, codardi!", "." },
  ["a5ebbc83d04af790"] = { "Manca poco all'apertura della ⟦Darkmoon Faire=Fiera di Lunacupa⟧. Torna più tardi a controllare se abbiamo finito.", "." },
  ["a5f1fceb7b930778"] = { "Gul'dan. Non è un nome che molti su Azeroth hanno sentito.\n\nPurtroppo, non è la risposta giusta.", "." },
  ["a5f206ac88e53951"] = { "Se il culto degli Al'Aketh non viene fermato presto, saremo tutti costretti con la forza a unirci a quei fanatici. Con la testa rasata io NON starei affatto bene.", "." },
  ["a5f2a0ee8aa8377c"] = { "Invasori! Invasori! Ci attaccano, ragazzi! Prendeteli!", "." },
  ["a5f9b120b3a2fef6"] = { "Signora ci ricuce e fascia quando ci colpiscono. Tu trovi lei nell'anello interno del ⟦Rogues' Quarter=Quartiere dei Ladri⟧.", "." },
})
